from calhacks_contracts import GateInput

from gatepy.registry import feature

TOO_LOW = 0.5


def _ratio(x: GateInput) -> float | None:
    m = x.references.market_median
    return x.listing.item.price / m if m else None


@feature("price_ratio", monotone=-1)
def price_ratio(x: GateInput) -> float:
    """Price / market median. Neutral 1.0 when there is no median for this product."""
    r = _ratio(x)
    return r if r is not None else 1.0


@feature("price_too_low", monotone=1)
def price_too_low(x: GateInput) -> float:
    r = _ratio(x)
    return 1.0 if r is not None and r < TOO_LOW else 0.0


@feature("has_median")
def has_median(x: GateInput) -> float:
    return 1.0 if x.references.market_median else 0.0

feature_sources.reviews.py:
from itertools import combinations

from calhacks_contracts import GateInput

from features._text import similarity
from gatepy.registry import feature


@feature("review_count")
def review_count(x: GateInput) -> float:
    return float(len(x.listing.reviews))


@feature("review_similarity_max", monotone=1)
def review_similarity_max(x: GateInput) -> float:
    """Highest similarity between any two reviews (cached embeddings when present, else word overlap)."""
    return max((similarity(a, b) for a, b in combinations(x.listing.reviews, 2)), default=0.0)


@feature("review_len_mean")
def review_len_mean(x: GateInput) -> float:
    rs = x.listing.reviews
    return sum(len(r.split()) for r in rs) / len(rs) if rs else 0.0


@feature("review_near_dup_ratio", monotone=1)
def review_near_dup_ratio(x: GateInput) -> float:
    """Share of reviews that repeat an earlier one almost word for word (one template posted many times)."""
    rs = x.listing.reviews
    if len(rs) < 2:
        return 0.0
    dup = 0
    for i in range(1, len(rs)):
        if any(similarity(rs[i], rs[j]) >= 0.8 for j in range(i)):
            dup += 1
    return dup / (len(rs) - 1)

feature_sources.trust.py:
"""Signals from references the attacker can't write: the known-seller list and when we first saw the wallet."""
from calhacks_contracts import GateInput

from gatepy.clock import days_since
from gatepy.registry import feature

MAX_DAYS = 3650.0


@feature("known_wallet", monotone=-1)
def known_wallet(x: GateInput) -> float:
    pay_to = x.listing.checkout.pay_to.lower()
    return 1.0 if any(k.pay_to.lower() == pay_to for k in x.references.known_sellers) else 0.0


@feature("payto_age_days", monotone=-1)
def payto_age_days(x: GateInput) -> float:
    """Days since this wallet first appeared to us (0 = brand new or never seen)."""
    return min(MAX_DAYS, days_since(x.references.pay_to_first_seen))
